@startuml

class Bus {
  + LineNumber : string
}

class Trajectory {
  + Status : string
}

class Line {
  + Category : string
}

class Approval {
  + Status : string
}

class TownAuthority {}

class MENSOUser {
  + HomeAddress : string
  + OfficeAddress : string
  + WorkingHours : string
}

class MENSOCard {}

class Trip {
  + Date : date
  + Time : time
}

class Invoice {
  + Month : string
  + TotalAmount : double
  + Discount : double
}

class Customer {
  + Name : string
}

Bus "0..*" -- "0..*" Trajectory : assigned to
Line "1" -- "1..*" Trajectory : groups
TownAuthority "1" -- "0..*" Approval : reviews
Trajectory "1" -- "0..*" Approval : undergoes
MENSOUser "1" -- "1" MENSOCard : possesses
MENSOUser "1" -- "0..*" Invoice : receives
MENSOUser "1" -- "0..*" Trip : performs
Line "1" -- "0..*" Trip : used for
Trip "1" -- "0..1" MENSOCard : uses
Invoice "1" -- "0..*" Trip : includes

@enduml

